pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        // c's balance is 0 here, so any positive withdrawal exceeds the balance.
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "over-withdrawal must revert");
    }
}
